ctx.fillRect(0, 0, W, H);

// Moon
ctx.beginPath();
ctx.arc(W * 0.75, H * 0.25, W * 0.1, 0, Math.PI * 2);
ctx.fillStyle = '#fff';
ctx.fill();

// Witch
const witchX = W * 0.25;
const witchY = H * 0.5;
const witchSize = W * 0.1;

// Witch body
ctx.fillStyle = '#8b4513'; // Brown
ctx.fillRect(witchX, witchY - witchSize, witchSize * 2, witchSize);

// Witch head
ctx.beginPath();
ctx.arc(witchX + witchSize, witchY - witchSize, witchSize * 0.6, 0, Math.PI * 2);
ctx.fillStyle = '#ff7f50'; // Orange
ctx.fill();

// Witch hat
ctx.beginPath();
ctx.moveTo(witchX + witchSize, witchY - witchSize * 1.2);
ctx.lineTo(witchX + witchSize * 0.5, witchY - witchSize * 1.5);
ctx.lineTo(witchX + witchSize * 1.5, witchY - witchSize * 1.5);
ctx.closePath();
ctx.fillStyle = '#8b4513'; // Brown
ctx.fill();

// Witch hair
ctx.fillStyle = '#ff7f50'; // Orange
ctx.fillRect(witchX - witchSize * 0.2, witchY - witchSize * 1.4, witchSize * 0.4, witchSize * 0.2);
ctx.fillRect(witchX + witchSize * 1.2, witchY - witchSize * 1.4, witchSize * 0.4, witchSize * 0.2);

// Witch wand
ctx.beginPath();
ctx.moveTo(witchX + witchSize * 0.5, witchY - witchSize * 1.5);
ctx.lineTo(witchX + witchSize * 0.9, witchY - witchSize * 1.8);
ctx.lineTo(witchX + witchSize * 1.3, witchY - witchSize * 1.5);
ctx.closePath();
ctx.fillStyle = '#ff7f50'; // Orange
ctx.fill();

// Witch flying
ctx.beginPath();
ctx.moveTo(witchX, witchY);
ctx.lineTo(witchX + witchSize * 0.5, witchY - witchSize * 0.5);
ctx.lineTo(witchX + witchSize * 1.0, witchY - witchSize * 1.0);
ctx.closePath();
ctx.fillStyle = '#8b4513'; // Brown
ctx.fill();

// Draw background
ctx.fillStyle = '#f0e6fa'; // Sky blue
ctx.fillRect(0, 0, W, H);

// Draw ground
ctx.fillStyle = '#9acd32'; // Grass green
ctx.fillRect(0, H - 100, W, 100);

// Draw doghouse
ctx.fillStyle = '#c0c0c0'; // Light gray
ctx.fillRect(W / 2 - 100, H - 200, 200, 100);
ctx.fillRect(W / 2 - 50, H - 250, 100, 50);

// Draw dog
ctx.fillStyle = '#ff8c00'; // Brown
ctx.fillRect(W / 2 - 75, H - 150, 50, 50);

// Draw tail
ctx.fillStyle = '#ff8c00';
ctx.beginPath();
ctx.moveTo(W / 2 - 75, H - 150);
ctx.lineTo(W / 2 - 50, H - 100);
ctx.lineTo(W / 2 - 25, H - 150);
ctx.closePath();
ctx.fill();

// Draw head
ctx.fillStyle = '#ffffff'; // White
ctx.beginPath();
ctx.arc(W / 2 - 75, H - 150, 25, 0, Math.PI * 2);
ctx.fill();

// Draw eyes
ctx.fillStyle = '#000000'; // Black
ctx.beginPath();
ctx.arc(W / 2 - 75 + 10, H - 150 - 10, 5, 0, Math.PI * 2);
ctx.arc(W / 2 - 75 - 10, H - 150 - 10, 5, 0, Math.PI * 2);
ctx.fill();

// Draw nose
ctx.fillStyle = '#ff8c00';
ctx.fillRect(W / 2 - 75 + 5, H - 150 - 20, 5, 5);
